<?php use App\Core\Security;?><div class="card mb-3"><div class="card-body"><h5>کاربران</h5><form method="post" action="/pricing/public/admin/users" class="row g-2"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><div class="col"><input name="username" class="form-control" placeholder="نام کاربری" required></div><div class="col"><input name="name" class="form-control" placeholder="نام" required></div><div class="col"><input name="password" type="password" minlength="8" class="form-control" placeholder="رمز اولیه" required></div><div class="col"><select name="groups[]" multiple class="form-select"><?php foreach($groups as $g):?><option value="<?=(int)$g['id']?>"><?=Security::e($g['name'])?></option><?php endforeach;?></select></div><div class="col-auto"><button class="btn btn-primary">ثبت کاربر</button></div></form></div></div><?php foreach($users as $u):?><div class="card mb-3"><div class="card-body"><h6><?=Security::e($u['name'])?> (<?=Security::e($u['username'])?>)</h6><form method="post" action="/pricing/public/admin/users/<?=(int)$u['id']?>/groups" class="mb-3"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><div class="row"><?php foreach($groups as $g):?><div class="col-md-3"><label><input type="checkbox" name="groups[]" value="<?=(int)$g['id']?>" <?=in_array((int)$g['id'],$u['groups'],true)?'checked':''?>> <?=Security::e($g['name'])?></label></div><?php endforeach;?></div><button class="btn btn-sm btn-outline-primary mt-2">ذخیره گروه‌ها</button></form><p class="text-muted">دسترسی نهایی = مجموع گروه‌ها با Override مستقیم کاربر.</p><form method="post" action="/pricing/public/admin/users/<?=(int)$u['id']?>/permissions"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><div class="row"><?php foreach($permissions as $p):$has=array_key_exists($p['code'],$u['overrides']);$effective=in_array($p['code'],$u['effective'],true);?><div class="col-md-6 col-lg-4 mb-2"><label class="small"><?=Security::e($p['name'])?></label><select name="permissions[<?=Security::e($p['code'])?>]" class="form-select form-select-sm"><option value="" <?=$has?'':'selected'?>>بدون Override — نهایی: <?=$effective?'مجاز':'غیرمجاز'?></option><option value="1" <?=$has&&$u['overrides'][$p['code']]===1?'selected':''?>>Override: اجازه</option><option value="0" <?=$has&&$u['overrides'][$p['code']]===0?'selected':''?>>Override: لغو</option></select></div><?php endforeach;?></div><button class="btn btn-sm btn-warning">ذخیره دسترسی نهایی</button></form></div></div><?php endforeach;?>